DO $$ BEGIN
  IF (SELECT count(*) FROM public.product_types) <> 86 OR (SELECT count(*) FROM public.product_type_rules) <> 86 THEN
    RAISE EXCEPTION 'Pilot rodzajów: brak podkategorii w bazie (oczekiwano 86 rodzajów i reguł).';
  END IF;
END $$;

ALTER TABLE public.products DISABLE TRIGGER trg_products_updated_at;
SELECT public.refresh_product_types();
ALTER TABLE public.products ENABLE TRIGGER trg_products_updated_at;

NOTIFY pgrst, 'reload schema';
